import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Stream from 'flarum/common/utils/Stream';
import extractText from 'flarum/common/utils/extractText';
import { call, t } from '../api';
/**
 * Search for a place, on the button or Enter only: Nominatim's usage policy
 * forbids search-as-you-type. Small enough to be copied into each form's chunk.
 */
export default class PlaceSearch extends Component {
  query = Stream('');
  searching = false;
  results = null;
  picked = '';
  view() {
    return m("div", {
      className: "Form-group MemberMapPlaceSearch"
    }, m("label", {
      for: this.attrs.id
    }, this.attrs.label), m("div", {
      className: "MemberMapPlaceSearch-row"
    }, m("input", {
      id: this.attrs.id,
      className: "FormControl",
      type: "search",
      autocomplete: "off",
      maxLength: 120,
      placeholder: extractText(t('location.search_placeholder')),
      bidi: this.query,
      onkeydown: e => {
        // Enter searches; it must not submit the form around it.
        if (e.key === 'Enter') {
          e.preventDefault();
          this.search();
        }
      }
    }), m(Button, {
      className: "Button",
      type: "button",
      loading: this.searching,
      disabled: this.query().trim().length < 2,
      onclick: () => this.search()
    }, t('location.search'))), this.results && m("ul", {
      className: "MemberMapPlaceSearch-results"
    }, this.results.length ? this.results.map(place => m("li", null, m("button", {
      type: "button",
      className: 'MemberMapPlaceSearch-result' + (this.picked === place.label ? ' active' : ''),
      onclick: () => {
        this.picked = place.label;
        this.attrs.onpick(place);
      }
    }, place.label))) : m("li", {
      className: "helpText"
    }, t('location.no_results'))));
  }
  search() {
    const q = this.query().trim();
    if (q.length < 2 || this.searching) return;
    this.searching = true;
    call('GET', '/geocode', {
      q
    }).then(data => this.results = data.places).catch(() => {}).finally(() => {
      this.searching = false;
      m.redraw();
    });
  }
}
flarum.reg.add('ernestdefoe-member-map', 'forum/components/PlaceSearch', PlaceSearch);